def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        # Extend a sufficiently long horizontal colored segment to the right edge.
        best = 0
        run = 0
        for v in row:
            if v != bg:
                run += 1
                best = max(best, run)
            else:
                run = 0
        if best >= 5:
            last = max(c for c, v in enumerate(row) if v != bg)
            if last < w - 1:
                for c in range(last + 1, w):
                    out[r][c] = 1
    return out
